using System.IO;
using System.Text.Json;
using Gitstar.Core;
using Gitstar.Desktop;

static class CacheCleanupChecks
{
    public static async Task Run(Action<bool,string> check,string parent)
    {
        var root=Path.Combine(parent,"cache-cleanup");using var store=new LocalStore(root);var account="user_a";var prefix="cache/"+account;
        var settings=new Settings{Account=account,ClientId="fixture-client",Bindings=[new(){AppId="fixture-app",Repository="owner/app"}],LocalGroups=[new("group","local","本地",["owner/app"])],PortableApps=[new("portable","Portable","1.0",root,true)],LastCheck=DateTimeOffset.UtcNow};store.Set("settings",settings);store.Set("auth","protected-fixture");store.Set("packages/user_a",new[]{"managed-package"});
        store.Set(prefix+"/repos",new[]{new Repository("owner/app","",false)});store.Set(prefix+"/groups",new[]{new StarGroup("id","group","GitHub",["owner/app"])});var release=new Release(1,"owner/app","1.0.0.0","name","notes",false,DateTimeOffset.UtcNow,"",[]);store.Set(prefix+"/releases",new[]{release});store.Set(prefix+"/installed",new InstalledSnapshot(DateTimeOffset.UtcNow,[new("fixture-app","App","0.9",root)]));store.Set(prefix+"/http-releases/owner/app/1",new{ETag="fixture"});
        store.Set("cache/userXa/http-releases/owner/app/1",new{ETag="other-account"});store.Set(prefix+"/my-projects",new[]{new ManagedProject("owner/app","",false,"main",true,true,false,DateTimeOffset.UtcNow,Id:1)});store.Set(prefix+"/my-projects/versions",new Dictionary<string,List<ProjectVersion>>{{"owner/app",[new(1,"1.0.0.0","name","notes",false,false,0,DateTimeOffset.UtcNow,"")]}});store.Set(prefix+"/my-projects/synced",DateTimeOffset.UtcNow);store.Set(prefix+"/my-projects/workspaces",new[]{new ProjectWorkspace("owner/app",root,"main")});store.Set(prefix+"/my-projects/automation",new[]{new ProjectAutomation("owner/app",root,root)});
        var serializedSettings=JsonSerializer.Serialize(settings);var summary=CacheCleanupService.Summaries(store,account);check(summary.Single(item=>item.Module==CacheModule.RecentUpdates).Bytes>0&&summary.Single(item=>item.Module==CacheModule.MyProjects).Items==3,"cache summaries report only module-owned records and exclude configuration keys");
        await CacheCleanupService.Clear(store,account,CacheModule.RecentUpdates,CancellationToken.None);var sizes=store.DocumentSizes();
        check(!sizes.ContainsKey(prefix+"/releases")&&!sizes.ContainsKey(prefix+"/http-releases/owner/app/1")&&sizes.ContainsKey("cache/userXa/http-releases/owner/app/1"),"recent cache cleanup removes owned HTTP pages without wildcard deletion of another account");
        check(store.Get(prefix+"/matched-releases",new List<Release>()).Single().Tag=="1.0.0.0"&&sizes.ContainsKey(prefix+"/installed")&&sizes.ContainsKey(prefix+"/my-projects/versions"),"legacy recent cleanup preserves local update versions and unrelated project or installed snapshots");
        check(store.Get(prefix+"/recent-cleared",false)&&store.Get("auth","")=="protected-fixture"&&JsonSerializer.Serialize(store.Get("settings",new Settings()))==serializedSettings&&sizes.ContainsKey("packages/user_a"),"cache cleanup preserves login settings portable apps bindings groups and download records");
        await CacheCleanupService.Clear(store,account,CacheModule.MyProjects,CancellationToken.None);sizes=store.DocumentSizes();check(!sizes.ContainsKey(prefix+"/my-projects/versions")&&sizes.ContainsKey(prefix+"/my-projects/workspaces")&&sizes.ContainsKey(prefix+"/my-projects/automation"),"my projects cache cleanup retains source workspace and automatic publication configurations");
        store.Set(prefix+"/releases",new[]{release});await CacheCleanupService.Clear(store,account,CacheModule.InstalledApps,CancellationToken.None);sizes=store.DocumentSizes();check(!sizes.ContainsKey(prefix+"/installed")&&!sizes.ContainsKey(prefix+"/matched-releases")&&sizes.ContainsKey(prefix+"/releases"),"installed cache cleanup preserves recent project releases while removing local snapshots");
        var tasks=new List<Operation>{new(){Id="done",State="完成"},new(){Id="canceled",State="已取消"},new(){Id="active",State="执行中"},new(){Id="paused",State="已暂停"},new(){Id="failed",State="失败：network"},new(){Id="pending",State="结果待核实"},new(){Id="canceled-remote",State="已取消 · 远程结果待核实",RemoteId=7}};store.Set("operations/user_a",tasks);
        var result=await CacheCleanupService.Clear(store,account,CacheModule.FinishedTasks,CancellationToken.None);var remaining=store.Get("operations/user_a",new List<Operation>());check(result.TaskRecords==2&&remaining.Count==5&&remaining.Any(operation=>operation.Id=="canceled-remote"&&operation.RemoteId==7),"task history cleanup retains active paused failed and unresolved remote operations including cancellations");
        var avatarRoot=Path.Combine(root,"avatars");Directory.CreateDirectory(avatarRoot);await File.WriteAllTextAsync(Path.Combine(avatarRoot,"owner_avatar.img"),"cached image");await File.WriteAllTextAsync(Path.Combine(avatarRoot,"personal.txt"),"keep");await File.WriteAllTextAsync(Path.Combine(root,"Gitstar.exe"),"keep application");var generation=AvatarCache.Generation;
        result=await CacheCleanupService.Clear(store,account,CacheModule.Avatars,CancellationToken.None);check(result.AvatarFiles==1&&!File.Exists(Path.Combine(avatarRoot,"owner_avatar.img"))&&File.Exists(Path.Combine(avatarRoot,"personal.txt"))&&File.Exists(Path.Combine(root,"Gitstar.exe"))&&AvatarCache.Generation>generation,"avatar cleanup removes only known cache filenames and invalidates in-flight image generation");
        var empty=false;try{await CacheCleanupService.Clear(store,account,CacheModule.None,CancellationToken.None);}catch(ArgumentException){empty=true;}check(empty,"empty cleanup selection cannot clear application data");
        store.Set("transaction-test","keep");var rolledBack=false;try{store.RemoveDocuments(["transaction-test"],[""]);}catch(ArgumentException){rolledBack=true;}check(rolledBack&&store.Get("transaction-test","")=="keep","invalid prefix rolls back all SQLite cache deletion changes");
        using var reopened=new LocalStore(root);check(reopened.Get("auth","")=="protected-fixture"&&reopened.Get(prefix+"/my-projects/workspaces",Array.Empty<ProjectWorkspace>()).Single().Folder==root&&reopened.Get("operations/user_a",new List<Operation>()).Count==5,"protected configuration and unfinished task state persist after cache compaction and database reopen");
    }
}
